mapper.select:
select l.*, p.purchase_no, pr.product_name, s.supplier_name
from pms_logistics l
left join pms_purchase p on p.purchase_id = l.purchase_id
left join pms_product pr on pr.product_id = l.product_id
left join pms_supplier s on s.supplier_id = l.supplier_id

    AND l.logistics_no like concat('%', #{logisticsNo}, '%')
    AND l.supplier_id = #{supplierId}
    AND l.purchase_id = #{purchaseId}
    AND l.pay_status = #{payStatus}
    AND l.carrier_id = #{carrierId}
    AND l.carrier like concat('%', #{carrier}, '%')
    AND l.abnormal_flag = #{abnormalFlag}
    AND l.create_time >= #{beginTime}
    AND l.create_time <= #{endTime}
    AND l.create_time >= #{params.beginTime}
    AND l.create_time <= #{params.endTime}

order by l.logistics_id desc

mapper.update:
update pms_logistics
carrier_id = #{carrierId}, carrier = #{carrier}, ship_time = #{shipTime}, arrive_time = #{arriveTime}, weight_volume = #{weightVolume}, freight = #{freight}, insurance_fee = #{insuranceFee}, other_fee = #{otherFee}, total_fee = #{totalFee}, pay_status = #{payStatus}, reconcile_time = #{reconcileTime}, reconcile_by = #{reconcileBy}, abnormal_flag = #{abnormalFlag}, abnormal_remark = #{abnormalRemark}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
where logistics_id = #{logisticsId}

mapper.select:
select ifnull(s.supplier_name,'未知厂家') as name, count(1) as billCount, ifnull(sum(l.total_fee),0) as totalFee from pms_logistics l left join pms_supplier s on s.supplier_id = l.supplier_id
AND l.create_time >= #{beginTime} AND l.create_time <= #{endTime}
group by l.supplier_id, s.supplier_name order by totalFee desc
